/**
 * Open Veryfront Studio in browser
 * @module cli/commands/studio
 */
import { canOpenBrowser, openBrowser } from "../../auth/browser.js";
import { readConfigFile, readConfigJsonFile } from "../../shared/config.js";
import { cwd } from "../../../src/platform/index.js";
import { join } from "../../../src/platform/compat/path/index.js";
import { createFileSystem } from "../../../src/platform/index.js";
import { brand, dim, muted } from "../../ui/index.js";
import { getEnvironmentConfig } from "../../../src/config/index.js";
import { getCloudDomain, resolveCliApiUrl } from "../../shared/constants.js";
/**
 * Build Studio URL with optional query params
 */
export function buildStudioUrl(project, options = {}, apiUrl) {
    const base = `https://${getCloudDomain(apiUrl)}/projects/${encodeURIComponent(project)}`;
    const params = new URLSearchParams();
    if (options.branch)
        params.set("branch", options.branch);
    if (options.file)
        params.set("path", options.file);
    const query = params.toString();
    return query ? `${base}?${query}` : base;
}
/**
 * Resolve project slug from environment, config, or directory
 */
async function resolveProjectSlug(projectDir, env = getEnvironmentConfig()) {
    if (env.projectSlug)
        return env.projectSlug;
    const config = await readConfigFile(projectDir);
    if (config?.projectSlug)
        return config.projectSlug;
    const fs = createFileSystem();
    const packagePath = join(projectDir, "package.json");
    try {
        if (await fs.exists(packagePath)) {
            const content = await fs.readTextFile(packagePath);
            const pkg = JSON.parse(content);
            const name = pkg?.name;
            if (name)
                return name.replace(/^@[^/]+\//, "").replace(/[^a-z0-9-]/gi, "-");
        }
    }
    catch {
        // Ignore errors
    }
    const dirName = projectDir.split(/[/\\]/).pop();
    if (dirName)
        return dirName.replace(/[^a-z0-9-]/gi, "-");
    throw new Error("Could not determine project slug");
}
/**
 * Open Veryfront Studio in browser
 */
export async function studioCommand(options = {}, env = getEnvironmentConfig()) {
    const project = options.project ?? (await resolveProjectSlug(cwd(), env));
    const config = await readConfigJsonFile(cwd());
    const url = buildStudioUrl(project, options, resolveCliApiUrl(env, config?.apiUrl));
    const opened = canOpenBrowser(env);
    console.log();
    if (!opened) {
        console.log("  " + muted("Open in browser:"));
        console.log();
        console.log("  " + brand(url));
        console.log();
        return { url, opened };
    }
    await openBrowser(url);
    console.log("  ✓ Opening " + brand(project) + " in Studio");
    console.log();
    console.log("  " + dim(url));
    console.log();
    return { url, opened };
}
